commands:
"C:\\Users\\tjdwo\\.cache\\codex-runtimes\\codex-primary-runtime\\dependencies\\native\\powershell\\pwsh.exe" -Command '$workspaceRoot = (Resolve-Path -LiteralPath .).Path
$temporaryAssets = (Resolve-Path -LiteralPath game/Assets/OfflineTestSupport).Path
$archiveAssets = [System.IO.Path]::GetFullPath((Join-Path $workspaceRoot '"'Logs\\OfflineTestSupport'))
foreach ("'$targetPath in @($temporaryAssets, $archiveAssets)) {
    if (-not $targetPath.StartsWith($workspaceRoot + '"'\\', [System.StringComparison]::OrdinalIgnoreCase)) { throw 'Temporary asset path escaped the workspace.' }
}
if (Test-Path -LiteralPath "'$archiveAssets) { throw '"'Archive path already exists.' }
Move-Item -LiteralPath "'$temporaryAssets -Destination $archiveAssets
Move-Item -LiteralPath (Join-Path $workspaceRoot '"'game\\Assets\\OfflineTestSupport.meta') -Destination (Join-Path "'$workspaceRoot '"'Logs\\OfflineTestSupport.meta')
Write-Output 'Archived temporary package copies under ignored Logs; removed them from game assets.'"
